// Browser-local media storage shared by the customer, driver, and admin views.
const DRIVER='demo-driver-john', CUSTOMER='customer-local';
const escapeText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const db=new Promise((resolve,reject)=>{const r=indexedDB.open('365-profile-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('media');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function record(key,value){const database=await db;return new Promise((resolve,reject)=>{const tx=database.transaction('media',value===undefined?'readonly':'readwrite'),store=tx.objectStore('media');const req=value===undefined?store.get(key):value===null?store.delete(key):store.put(value,key);tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const urls=new Set();
function url(blob){const u=URL.createObjectURL(blob);urls.add(u);return u}
function status(node,text){node.querySelector('[role=status]').textContent=text}
const navOriginal=new WeakMap();
async function navPhoto(id){const node=document.querySelector(id===DRIVER?'.d-user':'.avatar-button');if(!node)return;if(!navOriginal.has(node))navOriginal.set(node,node.innerHTML);const item=await record(id+':avatar');if(item&&node.isConnected){const img=new Image();img.src=url(item.blob);img.alt='';img.className='media-nav-photo';node.replaceChildren(img)}else if(!item&&node.isConnected){node.innerHTML=navOriginal.get(node)}}
async function avatar(host,id){
 if(host.dataset.mediaMounted)return;host.dataset.mediaMounted='true';
 const box=document.createElement('section');box.className='media-card media-avatar';box.innerHTML='<h2>Profile photo</h2><div class="media-photo" aria-label="Profile photo preview">No photo</div><label class="btn">Upload photo<input type="file" accept="image/jpeg,image/png,image/webp" hidden></label> <button type="button" class="btn outline">Remove photo</button><p>JPG, PNG or WebP, up to 5 MB.</p><p role="status" aria-live="polite"></p>';if(id===DRIVER)host.after(box);else host.prepend(box);
 const preview=box.querySelector('.media-photo'),remove=box.querySelector('button');
 async function draw(){const item=await record(id+':avatar');preview.replaceChildren();if(item){const img=new Image();img.src=url(item.blob);img.alt='Profile photo';preview.append(img);if(id===DRIVER){const initials=document.querySelector('.d-profile-banner .d-initials');if(initials){initials.replaceChildren(img.cloneNode());initials.classList.add('media-photo')}}}else{preview.textContent='No photo';const initials=document.querySelector('.d-profile-banner .d-initials');if(initials&&id===DRIVER){let p={};try{p=JSON.parse(localStorage.getItem('365-driver-profile'))||{}}catch{}initials.textContent=(p.firstName||'John')[0]+(p.lastName||'Miller')[0]}}remove.disabled=!item;await navPhoto(id)}
 const uploadLabel=box.querySelector('label');uploadLabel.tabIndex=0;uploadLabel.setAttribute('role','button');uploadLabel.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();uploadLabel.querySelector('input').click()}};
 box.querySelector('input').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Choose a JPG, PNG or WebP photo up to 5 MB.');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob)throw Error('Unable to read this photo.');await record(id+':avatar',{blob});await draw();status(box,'Photo saved on this device.')}catch(error){status(box,error.message)}event.target.value=''};
 remove.onclick=async()=>{try{await record(id+':avatar',null);await draw();status(box,'Photo removed.')}catch{status(box,'Unable to remove photo. Please try again.')}};await draw();
}
function mount(){for(const [selector,id] of [['.d-user',DRIVER],['.avatar-button',CUSTOMER]]){const n=document.querySelector(selector);if(n&&!n.dataset.mediaChecked){n.dataset.mediaChecked='true';navPhoto(id).catch(()=>{})}}const route=location.hash.split('?')[0];if(route==='#/driver/profile'){const host=document.querySelector('.d-profile-banner');if(host)avatar(host,DRIVER).catch(()=>{});}if(route==='#/profile'){const host=document.querySelector('main');if(host)avatar(host,CUSTOMER).catch(()=>{})}const match=route.match(/^#\/admin\/(drivers|customers)\/(.+)$/);if(match){const id=decodeURIComponent(match[2]),host=document.querySelector('.a-account-detail');if(host&&!host.dataset.mediaMounted){host.dataset.mediaMounted='true';record(id+':avatar').then(item=>{if(item&&host.isConnected){const img=new Image();img.src=url(item.blob);img.alt='Profile photo';img.className='media-admin-avatar';host.querySelector('.a-initials')?.replaceWith(img)}}).catch(()=>{})}}}
let queued=false;new MutationObserver(()=>{if(!queued){queued=true;queueMicrotask(()=>{queued=false;mount()})}}).observe(document.getElementById('app'),{childList:true,subtree:true});window.addEventListener('hashchange',()=>{for(const u of urls)URL.revokeObjectURL(u);urls.clear();mount()});mount();
